{
 "filePath": "/Users/darwin/Desktop/tests-ai-coding-agent/test04/src/types/subscription.ts",
 "content": "export interface Subscription {\n id: string;\n nome: string;\n valor: number;\n dataVencimento: string; // ISO date string\n categoria: Categoria;\n}\n\nexport type Categoria = 'Streaming' | 'Trabalho' | 'Saúde' | 'Educação' | 'Outros';\n\nexport const CATEGORIAS: Categoria[] = [\n 'Streaming',\n 'Trabalho',\n 'Saúde',\n 'Educação',\n 'Outros',\n];\n\nexport const CATEGORIA_COLORS: Record = {\n Streaming: '#ef4444', // red\n Trabalho: '#3b82f6', // blue\n Saúde: '#10b981', // green\n Educação: '#f59e0b', // amber\n Outros: '#8b5cf6', // purple\n};\n"
}


{
 "filePath": "/Users/darwin/Desktop/tests-ai-coding-agent/test04/src/hooks/useLocalStorage.ts",
 "content": "import { useState, useEffect } from 'react';\n\nexport function useLocalStorage(\n key: string,\n initialValue: T\n): [T, (value: T | ((val: T) => T)) => void] {\n // Get initial value from localStorage or use provided initial value\n const [storedValue, setStoredValue] = useState(() => {\n try {\n const item = window.localStorage.getItem(key);\n return item ? JSON.parse(item) : initialValue;\n } catch (error) {\n console.error(`Error loading ${key} from localStorage:`, error);\n return initialValue;\n }\n });\n\n // Update localStorage when state changes\n const setValue = (value: T | ((val: T) => T)) => {\n try {\n const valueToStore = value instanceof Function ? value(storedValue) : value;\n setStoredValue(valueToStore);\n window.localStorage.setItem(key, JSON.stringify(valueToStore));\n } catch (error) {\n console.error(`Error saving ${key} to localStorage:`, error);\n }\n };\n\n return [storedValue, setValue];\n}\n"
}


{
 "filePath": "/Users/darwin/Desktop/tests-ai-coding-agent/test04/src/context/ThemeContext.tsx",
 "content": "import React, { createContext, useContext, useEffect } from 'react';\nimport { useLocalStorage } from '../hooks/useLocalStorage';\n\ntype Theme = 'light' | 'dark';\n\ninterface ThemeContextType {\n theme: Theme;\n toggleTheme: () => void;\n}\n\nconst ThemeContext = createContext(undefined);\n\nexport function ThemeProvider({ children }: { children: React.ReactNode }) {\n const [theme, setTheme] = useLocalStorage('theme', 'light');\n\n useEffect(() => {\n const root = window.document.documentElement;\n root.classList.remove('light', 'dark');\n root.classList.add(theme);\n }, [theme]);\n\n const toggleTheme = () => {\n setTheme((prev) => (prev === 'light' ? 'dark' : 'light'));\n };\n\n return (\n \n {children}\n \n );\n}\n\nexport function useTheme() {\n const context = useContext(ThemeContext);\n if (context === undefined) {\n throw new Error('useTheme must be used within a ThemeProvider');\n }\n return context;\n}\n"
}


{
 "filePath": "/Users/darwin/Desktop/tests-ai-coding-agent/test04/src/context/SubscriptionContext.tsx",
 "content": "import React, { createContext, useContext, ReactNode } from 'react';\nimport { Subscription } from '../types/subscription';\nimport { useLocalStorage } from '../hooks/useLocalStorage';\n\ninterface SubscriptionContextType {\n subscriptions: Subscription[];\n addSubscription: (subscription: Omit) => void;\n updateSubscription: (id: string, subscription: Omit) => void;\n deleteSubscription: (id: string) => void;\n}\n\nconst SubscriptionContext = createContext(undefined);\n\nexport function SubscriptionProvider({ children }: { children: ReactNode }) {\n const [subscriptions, setSubscriptions] = useLocalStorage('subscriptions', []);\n\n const addSubscription = (subscription: Omit) => {\n const newSubscription: Subscription = {\n ...subscription,\n id: crypto.randomUUID(),\n };\n setSubscriptions((prev) => [...prev, newSubscription]);\n };\n\n const updateSubscription = (id: string, subscription: Omit) => {\n setSubscriptions((prev) =>\n prev.map((sub) => (sub.id === id ? { ...subscription, id } : sub))\n );\n };\n\n const deleteSubscription = (id: string) => {\n setSubscriptions((prev) => prev.filter((sub) => sub.id !== id));\n };\n\n return (\n \n {children}\n \n );\n}\n\nexport function useSubscriptions() {\n const context = useContext(SubscriptionContext);\n if (context === undefined) {\n throw new Error('useSubscriptions must be used within a SubscriptionProvider');\n }\n return context;\n}\n"
}


{
 "filePath": "/Users/darwin/Desktop/tests-ai-coding-agent/test04/src/utils/calculations.ts",
 "content": "import { Subscription } from '../types/subscription';\n\nexport function calculateTotalMonthly(subscriptions: Subscription[]): number {\n return subscriptions.reduce((total, sub) => total + sub.valor, 0);\n}\n\nexport function findMostExpensive(subscriptions: Subscription[]): Subscription | null {\n if (subscriptions.length === 0) return null;\n return subscriptions.reduce((max, sub) => (sub.valor > max.valor ? sub : max));\n}\n\nexport function findNextDue(subscriptions: Subscription[]): Subscription | null {\n if (subscriptions.length === 0) return null;\n \n const today = new Date();\n const upcoming = subscriptions\n .filter((sub) => new Date(sub.dataVencimento) >= today)\n .sort((a, b) => new Date(a.dataVencimento).getTime() - new Date(b.dataVencimento).getTime());\n \n return upcoming[0] || null;\n}\n\nexport function calculateByCategory(subscriptions: Subscription[]): Record {\n return subscriptions.reduce((acc, sub) => {\n acc[sub.categoria] = (acc[sub.categoria] || 0) + sub.valor;\n return acc;\n }, {} as Record);\n}\n"
}


{
 "filePath": "/Users/darwin/Desktop/tests-ai-coding-agent/test04/src/utils/formatters.ts",
 "content": "export function formatCurrency(value: number): string {\n return new Intl.NumberFormat('pt-BR', {\n style: 'currency',\n currency: 'BRL',\n }).format(value);\n}\n\nexport function formatDate(dateString: string): string {\n const date = new Date(dateString);\n return new Intl.DateFormat('pt-BR', {\n day: '2-digit',\n month: '2-digit',\n year: 'numeric',\n }).format(date);\n}\n\nexport function formatDateShort(dateString: string): string {\n const date = new Date(dateString);\n return new Intl.DateFormat('pt-BR', {\n day: '2-digit',\n month: 'short',\n }).format(date);\n}\n\nexport function getDaysUntil(dateString: string): number {\n const today = new Date();\n const target = new Date(dateString);\n const diffTime = target.getTime() - today.getTime();\n const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));\n return diffDays;\n}\n"
}


{
 "filePath": "/Users/darwin/Desktop/tests-ai-coding-agent/test04/src/utils/validators.ts",
 "content": "export interface ValidationError {\n field: string;\n message: string;\n}\n\nexport function validateSubscription(data: {\n nome: string;\n valor: string;\n dataVencimento: string;\n categoria: string;\n}): ValidationError[] {\n const errors: ValidationError[] = [];\n\n // Validate nome\n if (!data.nome || data.nome.trim().length === 0) {\n errors.push({ field: 'nome', message: 'Nome é obrigatório' });\n }\n\n // Validate valor\n const valor = parseFloat(data.valor);\n if (isNaN(valor)) {\n errors.push({ field: 'valor', message: 'Valor deve ser um número' });\n } else if (valor <= 0) {\n errors.push({ field: 'valor', message: 'Valor deve ser positivo' });\n }\n\n // Validate dataVencimento\n if (!data.dataVencimento) {\n errors.push({ field: 'dataVencimento', message: 'Data de vencimento é obrigatória' });\n } else {\n const date = new Date(data.dataVencimento);\n if (isNaN(date.getTime())) {\n errors.push({ field: 'dataVencimento', message: 'Data inválida' });\n }\n }\n\n // Validate categoria\n if (!data.categoria) {\n errors.push({ field: 'categoria', message: 'Categoria é obrigatória' });\n }\n\n return errors;\n}\n"
}


