 "filePath": "/Users/darwin/Desktop/tests-ai-coding-agent/test04/src/hooks/useLocalStorage.ts",
 "code": "import { useState } from 'react';\n\nexport function useLocalStorage(\n key: string,\n initialValue: T\n): [T, (value: T | ((val: T) => T)) => void] {\n // Get initial value from localStorage or use provided initial value\n const [storedValue, setStoredValue] = useState(() => {\n try {\n const item = window.localStorage.getItem(key);\n return item ? JSON.parse(item) : initialValue;\n } catch (error) {\n console.error(`Error loading ${key} from localStorage:`, error);\n return initialValue;\n }\n });\n\n // Update localStorage when state changes\n const setValue = (value: T | ((val: T) => T)) => {\n try {\n const valueToStore = value instanceof Function ? value(storedValue) : value;\n setStoredValue(valueToStore);\n window.localStorage.setItem(key, JSON.stringify(valueToStore));\n } catch (error) {\n console.error(`Error saving ${key} to localStorage:`, error);\n }\n };\n\n return [storedValue, setValue];\n}"
}


{
 "explanation": "Reescrever arquivo completo de calculations",
 "filePath": "/Users/darwin/Desktop/tests-ai-coding-agent/test04/src/utils/calculations.ts",
 "code": "import type { Subscription } from '../types/subscription';\n\nexport function calculateTotalMonthly(subscriptions: Subscription[]): number {\n return subscriptions.reduce((total, sub) => total + sub.valor, 0);\n}\n\nexport function findMostExpensive(subscriptions: Subscription[]): Subscription | null {\n if (subscriptions.length === 0) return null;\n return subscriptions.reduce((max, sub) => (sub.valor > max.valor ? sub : max));\n}\n\nexport function findNextDue(subscriptions: Subscription[]): Subscription | null {\n if (subscriptions.length === 0) return null;\n \n const today = new Date();\n const upcoming = subscriptions\n .filter((sub) => new Date(sub.dataVencimento) >= today)\n .sort((a, b) => new Date(a.dataVencimento).getTime() - new Date(b.dataVencimento).getTime());\n \n return upcoming[0] || null;\n}\n\nexport function calculateByCategory(subscriptions: Subscription[]): Record {\n return subscriptions.reduce((acc, sub) => {\n acc[sub.categoria] = (acc[sub.categoria] || 0) + sub.valor;\n return acc;\n }, {} as Record);\n}"
}


