 "code": "import { createContext, useContext } from 'react';\nimport type { ReactNode } from 'react';\nimport type { Subscription } from '../types/subscription';\nimport { useLocalStorage } from '../hooks/useLocalStorage';\n\ninterface SubscriptionContextType {\n subscriptions: Subscription[];\n addSubscription: (subscription: Omit) => void;\n updateSubscription: (id: string, subscription: Omit) => void;\n deleteSubscription: (id: string) => void;\n}\n\nconst SubscriptionContext = createContext(undefined);\n\nexport function SubscriptionProvider({ children }: { children: ReactNode }) {\n const [subscriptions, setSubscriptions] = useLocalStorage('subscriptions', []);\n\n const addSubscription = (subscription: Omit) => {\n const newSubscription: Subscription = {\n ...subscription,\n id: crypto.randomUUID(),\n };\n setSubscriptions((prev) => [...prev, newSubscription]);\n };\n\n const updateSubscription = (id: string, subscription: Omit) => {\n setSubscriptions((prev) =>\n prev.map((sub) => (sub.id === id ? { ...subscription, id } : sub))\n );\n };\n\n const deleteSubscription = (id: string) => {\n setSubscriptions((prev) => prev.filter((sub) => sub.id !== id));\n };\n\n return (\n \n {children}\n \n );\n}\n\nexport function useSubscriptions() {\n const context = useContext(SubscriptionContext);\n if (context === undefined) {\n throw new Error('useSubscriptions must be used within a SubscriptionProvider');\n }\n return context;\n}"
}


